import {mapGetters} from "vuex";
import arrtForm from './components/functionPosition/arrtForm'
import {globalattrSearch, globalattrDel, erpmaintainList} from "@/api/assets/functionPosition";

export default {
  components: {
    arrtForm,
  },
  computed: {
    ...mapGetters(["permission", "userInfo", 'userDetail'])
  },
  data() {
    return {
      swerkList: [],
      operationList: [
        {
          dictKey: 'C',
          dictValue: '创建'
        },
        {
          dictKey: 'M',
          dictValue: '修改'
        },
        {
          dictKey: 'D',
          dictValue: '删除'
        },
      ],
      beberList: [
        {
          dictKey: '003',
          dictValue: '省公司'
        },
        {
          dictKey: '004',
          dictValue: '县公司'
        },
      ],
      zsbdydjList: [
        {
          dictKey: '07',
          dictValue: '交流220V'
        }
      ],
      statusList: [
        {
          dictKey: 0,
          dictValue: '同步成功'
        },
        {
          dictKey: 1,
          dictValue: '同步失败'
        }
      ],
      selectionList: [],
      searchForm: {
        current: 1,
        size: 20,
        swerk: undefined,
        beber: undefined,
        trlnr: undefined,
        pltxt: undefined,
        tplma: undefined,
      },
      total: 0,

      tableData: [],
      tableHeight: undefined,
      tableLoading: false,
      // 弹窗
      showForm: false,
      showType: '',
      arrtId: '',

      exportList: [
        {id: 'D001', name: '导出选中'},
        {id: 'D002', name: '导出搜索'},
        {id: 'D003', name: '导出全部'},
        {id: 'D004', name: '导出记录'},
      ]
    }
  },
  mounted() {
    this.setPageContentHeight();
    this.setTableHeight();
    this.getDict();
    this.getList();
  },
  methods: {
    selectionChange(selection) {
      //点击选择事件
      this.selectionList = selection.map(item => item.trlnr);
    },
    showDictLable(code, dictList) {
      //字典回显
      if (dictList != null && code !== '') {
        let items = dictList.filter(item => item.dictKey == code);
        if (items != null && items.length > 0) {
          return items[0].dictValue;
        }
      }
      return code;
    },
    showSwerkLable(code, dictList) {
      //字典回显
      if (dictList != null && code !== '') {
        let items = dictList.filter(item => item.code == code);
        if (items != null && items.length > 0) {
          return items[0].name;
        }
      }
      return code;
    },
    handleQuery() {
      this.searchForm.current = 1;
      this.getList();
    },
    handleReset() {
      this.searchForm.swerk = undefined;
      this.searchForm.beber = undefined;
      this.searchForm.trlnr = undefined;
      this.searchForm.pltxt = undefined;
      this.searchForm.tplma = undefined;
      this.getList();
    },
    getDict() {
      erpmaintainList({current: 1, size: 200}).then(res => {
        this.swerkList = res.data.records
      })
    },
    // 设置表格高度
    setTableHeight() {
      let bodyBox = document.getElementsByClassName('page_body');
      this.tableHeight = (bodyBox[0].offsetHeight - 50) + 'px'
    },
    getList() {
      this.tableLoading = true;
      if (this.userDetail.regionCode !== '37') {
        this.searchForm.swerk = this.userDetail.erpUnitCode;
      }
      globalattrSearch(this.searchForm).then(res => {
        this.tableData = res.data.records;
        this.total = res.data.total;
        this.tableLoading = false
      }).catch(() => {
        this.tableLoading = false
      })
    },
    // 删除
    delArrt(row) {
      this.$confirm('确定是否删除?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        let ids;
        ids = row.join(',')

        globalattrDel({ids: ids}).then(res => {
          this.$message({
            type: 'success',
            message: '删除成功！'
          });
          this.getList()
        })
      })
    },
    // 编辑
    editArrt(row) {
      this.showType = '修改'
      this.arrtId = row.trlnr
      this.showForm = true
    },
    tbClick(type) {
      this.$message.success(type)
    },
    saveGlobalArrt() {
      this.showForm = false
      this.getList()
    }
  }
}
